function P.swapTarget(pot, pool, var)
    local ratio = tonumber(val("f_ratio", 3)) or 3
    local m = mult()
    local cash = M.cash()
    local open = E.openTime(pool, var)
    local best, bestGain
    for _, s in ipairs(M.pads()) do
        local id = charOn(s)
        local it = id and item(id)
        if it and not it.Favorited then
            local old = E.potentialOfItem(it)
            if old > 0 and pot >= old * ratio then
                local cur = (tonumber(s:GetAttribute("CharacterRatePerSecond")) or 0) * m
                local spent = (tonumber(s:GetAttribute("UpgradeCost")) or 0) * 3.86
                local rebuild = spent * (old / pot) ^ 0.813
                local lost = cur * open
                if open <= 1200 and rebuild + lost <= math.max(cash * 0.5, income() * 300) then
                    local g = pot / old
                    if not bestGain or g > bestGain then best, bestGain = s, g end
                end
            end
        end
    end
    return best
end
function P.useful(c) return #P.empty() > 0 or (on("f_replace") and P.swapTarget(c.pot, c.pool, c.var) ~= nil) end
function P.replace()
    if not on("f_replace") or #P.empty() > 0 then return false end
    for _, c in ipairs(P.cubes()) do
        local w = P.swapTarget(c.pot, c.pool, c.var)
        if w then
            local rm = M.prompt(w, "CoreRemove")
            if rm and rm.Enabled then
                local oldId = w:GetAttribute("ItemId")
                S.task = __T["Swapping a weak unit"]
                M.press(rm)
                if M.waitFor(function() local st = w:GetAttribute("State") return st == nil or st == "Empty" end, 1.5) then
                    if oldId then P.swapped[oldId] = true end
                    S.replaced += 1
                    LOG("swap pad", w:GetAttribute("PadIndex"), c.pool, c.var)
                    return P.placeOn(w, c.id)
                end
            end
            return false
        end
    end
    return false
end
P.swapped = {}
function P.wantOffer(pool, variant, price)
    local cash = M.cash() - (E.tierHold or 0)
    if not price or price <= 0 or price > cash then return false end
    local pot = E.offerPotential(pool, variant)
    local need = #P.empty() - #P.cubes()
    if need > 0 then return price <= math.max(cash * 0.35, income() * 60) end
    if not on("f_replace") then return false end
    for _, c in ipairs(P.cubes()) do if c.pot >= pot then return false end end
    return P.swapTarget(pot, pool, variant) ~= nil and price <= math.max(cash * 0.25, income() * 120)
end
P.seq = 0
P.tokenOrder = { "Unknown", "Admin", "Flow State", "Predator", "Shadow", "Monster" }
function P.useToken()
    if not on("f_tokens") or P.tokenVar or not P.maxBase then return false end
    local u = M.data().Utility or {}
    for _, v in ipairs(P.tokenOrder) do
        local key = (v:gsub(" ", "")) .. "VariantToken"
        if (tonumber(u[key]) or 0) > 0 and M.cash() - (E.tierHold or 0) >= P.maxBase * E.varMult(v) then
            M.fire("Conveyor.UseVariantToken", v)
            P.tokenVar = v
            LOG("variant token", v)
            return true
        end
    end
    return false
end
function P.rollSession(maxTime)
    local cp = M.offerPart()
    if not cp then return false end
    M.tp(cp.Position)
    task.wait(0.25)
    local t0 = os.clock()
    local rolledAt = 0
    local did = false
    while RUNNING and on("f_farm") and os.clock() - t0 < maxTime do
        local need = #P.empty() - #P.cubes()
        if need <= 0 and not on("f_replace") then break end
        if not M.near(cp.Position, 8) then M.tp(cp.Position) task.wait(0.2) end
        local id, pool, var, price = cp:GetAttribute("RollId"), cp:GetAttribute("Pool"), cp:GetAttribute("Variant"), tonumber(cp:GetAttribute("Price"))
        if price and price > 0 and pool then
            local base = price / E.varMult(var)
            if base > (P.maxBase or 0) then P.maxBase = base end
        end
        local forced = P.tokenVar and var == P.tokenVar
        if forced then P.tokenVar = nil end
        if id and pool and price and price > 0 and (P.wantOffer(pool, var, price) or (forced and price <= M.cash())) then
            S.want = price
            local w = 0.8 - (os.clock() - rolledAt)
            if w > 0 then task.wait(w) end
            local n0 = #P.cubes()
            M.fire("Conveyor.Purchase", id)
            if M.waitFor(function() return #P.cubes() > n0 end, 1.5) then
                S.cubes += 1
                did = true
                P.cubePrice = price
                P.lastBuy = os.clock()
                LOG("cube", pool, var, price)
            end
            S.want = 0
            if #P.empty() - #P.cubes() <= 0 then break end
        end
        S.task = __T["Rolling cubes"]
        P.useToken()
        P.seq += 1
        local r0 = cp:GetAttribute("RollId")
        local cd = (tonumber(lp:GetAttribute("RollCooldown")) or 1) + 0.05
        local wait = cd - (os.clock() - rolledAt)
        if wait > 0 then task.wait(wait) end
        M.fire("Conveyor.Roll", P.seq)
        rolledAt = os.clock()
        M.waitFor(function() return cp:GetAttribute("RollId") ~= r0 end, 2)
    end
    S.want = 0
    return did
end
