function P.sellJunk()
    if not on("f_sellJunk") or os.clock() - P.lastJunk < 45 then return false end
    local units, other = 0, 0
    for id, it in pairs(M.data().Items or {}) do
        if it.Kind == "Character" and it.Location == "Inventory" and not it.Favorited then
            if P.swapped[id] then units += 1 else other += 1 end
        end
    end
    local junkCubes = 0
    if #P.empty() == 0 then
        for _, c in ipairs(P.cubes()) do if not P.useful(c) and E.varMult(c.var) < 10 then junkCubes += 1 end end
        if junkCubes ~= #P.cubes() then junkCubes = 0 end
    end
    if (units == 0 or other > 0) and junkCubes == 0 then return false end
    P.lastJunk = os.clock()
    S.task = __T["Selling old units"]
    if units > 0 and other == 0 then
        if P.sellCat("Characters") then for id in pairs(P.swapped) do if not item(id) then P.swapped[id] = nil end end end
    end
    if junkCubes > 0 and os.clock() - (P.lastBuy or 0) > 180 then P.sellCat("Coffins") end
    return true
end
