function X.runCourse(name)
    local c = Workspace["Sky Obbies"]:FindFirstChild(name)
    local start = c and c:FindFirstChild("Start")
    local sp = start and (start:IsA("BasePart") and start or start:FindFirstChildWhichIsA("BasePart", true))
    local pad = c and c:FindFirstChild("Reward Pad")
    local r = M.root()
    if not (sp and pad and r) then return false end
    local st = {}
    for _, p in ipairs(c:GetChildren()) do
        if p:IsA("BasePart") and D.ObbyRun and D.ObbyRun.isStation(p.Name) then st[#st + 1] = p end
    end
    local cur = sp.Position
    local ordered = {}
    while #st > 0 do
        local bi, bd = 1, math.huge
        for i, p in ipairs(st) do local dd = (p.Position - cur).Magnitude if dd < bd then bi, bd = i, dd end end
        local p = table.remove(st, bi)
        ordered[#ordered + 1] = p
        cur = p.Position
    end
    local gates, avoid = {}, {}
    for _, g in ipairs(c:GetDescendants()) do
        if g:IsA("BasePart") then
            if g:GetAttribute("GateCycle") then gates[#gates + 1] = g end
            if g:GetAttribute("GateCycle") or g:GetAttribute("ObbyHazard") or g.Name:lower():find("cursed") then avoid[#avoid + 1] = g end
        end
    end
    local function gateOn(p)
        for _, g in ipairs(gates) do
            local f = Vector3.new(g.Position.X - p.Position.X, 0, g.Position.Z - p.Position.Z)
            if f.Magnitude < math.max(p.Size.X, p.Size.Z) / 2 + 1 then return g end
        end
    end
    local function gateWait(g)
        if not g then return end
        local cyc = tonumber(g:GetAttribute("GateCycle")) or 4.8
        local closed = tonumber(g:GetAttribute("GateClosed")) or 2.2
        local ph = tonumber(g:GetAttribute("GatePhase")) or 0
        local need = math.min(0.9, (cyc - closed) - 0.15)
        local t0 = os.clock()
        while os.clock() - t0 < cyc + 1 do
            local m = (M.now() + ph) % cyc
            if m >= closed + 0.05 and cyc - m >= need then break end
            task.wait(0.03)
        end
    end
    local function hazardOn(p)
        for _, g in ipairs(avoid) do
            local f = Vector3.new(g.Position.X - p.Position.X, 0, g.Position.Z - p.Position.Z)
            if f.Magnitude < math.max(p.Size.X, p.Size.Z) / 2 + 1 and math.abs(g.Position.Y - p.Position.Y) < 8 then return g end
        end
    end
    local function spotOn(p, from)
        local g = hazardOn(p)
        if not g then return p.Position end
        local dir = Vector3.new(p.Position.X - from.X, 0, p.Position.Z - from.Z)
        dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.new(0, 0, -1)
        local half = (math.abs(dir.X) * p.Size.X + math.abs(dir.Z) * p.Size.Z) / 2
        local gthick = (math.abs(dir.X) * g.Size.X + math.abs(dir.Z) * g.Size.Z) / 2
        local along = Vector3.new(g.Position.X - p.Position.X, 0, g.Position.Z - p.Position.Z):Dot(dir)
        local off = half - 0.7
        if along > 0 and along + gthick + 3 > off then off = -(half - 0.7) end
        return p.Position + dir * off
    end
    S.task = __T["Obby: "] .. name
    local last0 = X.lastReward(name)
    local total, last = 0, sp.Position
    for _, p in ipairs(ordered) do total += (p.Position - last).Magnitude last = p.Position end
    total += (pad.Position - last).Magnitude
    r.CFrame = CFrame.new(sp.Position + Vector3.new(0, 4, 0))
    task.wait(0.8)
    local prev = sp.Position
    for _, p in ipairs(ordered) do
        if not RUNNING or not lp:GetAttribute("InObby") then LOG("obby left", name) return false end
        task.wait(math.max((p.Position - prev).Magnitude / 13, 0.6))
        local g = gateOn(p)
        gateWait(g)
        local spot = spotOn(p, prev)
        prev = p.Position
        r = M.root()
        if r then r.CFrame = CFrame.new(spot + Vector3.new(0, p.Size.Y / 2 + 2, 0)) end
        if g then task.wait(0.35) end
    end
    task.wait(math.max((pad.Position - prev).Magnitude / 13, 0.6))
    r = M.root()
    local pdir = Vector3.new(pad.Position.X - prev.X, 0, pad.Position.Z - prev.Z)
    pdir = pdir.Magnitude > 0.1 and pdir.Unit or Vector3.zero
    if r then r.CFrame = CFrame.new(pad.Position - pdir * 2.3 + Vector3.new(0, pad.Size.Y / 2 + 2.5, 0)) end
    local ok = M.waitFor(function() return X.lastReward(name) > last0 or (tonumber(lp:GetAttribute("ObbyReadyAt_" .. name)) or 0) > M.now() + 60 end, 10)
    if ok then S.obbies += 1 LOG("obby", name) else LOG("obby fail", name) end
    return ok
end
