G.tokenSkip = {}
function G.tokenStep()
    if not on("g_grade") then return false end
    local tokens = tonumber((M.data().Utility or {}).GradeToken) or 0
    if tokens <= 0 then return false end
    local it = G.pick()
    if not it then return false end
    local g0 = it.Grade or "F"
    M.fire("Grade.Roll", it.Id, "Token", g0)
    task.wait(0.6)
    S.grades += 1
    local now = item(it.Id)
    if now and now.Grade ~= g0 then LOG("grade token", it.Type, g0, "->", now.Grade) end
    return true
end
function G.traitCash(name)
    local t = name and D.Traits and D.Traits.get and gcall(D.Traits.get, name)
    return t and tonumber(t.Cash) or 1
end
G.traitSkip = {}
function G.trait()
    if not on("g_trait") then return false end
    local tokens = tonumber((M.data().Utility or {}).TraitToken) or 0
    if tokens <= 0 then return false end
    local goal = {}
    local v = Opt and Opt.g_traits and Opt.g_traits.Value
    for _, n in ipairs({ "Midas", "Angelic", "Sovereign", "Phoenix", "Assassin" }) do if type(v) ~= "table" or v[n] then goal[n] = true end end
    local best, br
    for _, s in ipairs(M.pads()) do
        local id = charOn(s)
        local it = id and item(id)
        if it and not goal[it.Trait or ""] and (G.traitSkip[id] or 0) < os.clock() then
            local r = tonumber(s:GetAttribute("CharacterRatePerSecond")) or 0
            if not br or r > br then best, br = it, r end
        end
    end
    if not best then return false end
    local t0 = best.Trait
    local rare = t0 ~= nil and G.traitCash(t0) >= 1.2 or (t0 == "Berserk" or t0 == "Emperor")
    M.fire("Trait.Roll", best.Id, rare and true or false)
    task.wait(1)
    local now = item(best.Id)
    local t1 = now and now.Trait
    local left = tonumber((M.data().Utility or {}).TraitToken) or 0
    if t1 == t0 and left >= tokens then G.traitSkip[best.Id] = os.clock() + 60 return false end
    S.traits += 1
    if t1 ~= t0 then LOG("trait", best.Type, tostring(t0), "->", tostring(t1)) end
    return true
end
