        for i, cl in pairs(sq and sq.Claimed or {}) do
            if cl == false then M.fire("ShrineQuest.Claim", tonumber(i) or i) task.wait(0.3) end
        end
    end
    if on("r_skips") then
        local u = d.Utility or {}
        for _, k in ipairs({ "TimeSkip24Hour", "TimeSkip12Hour", "TimeSkip6Hour", "TimeSkip2Hour", "TimeSkip30Min", "TimeSkip5Min" }) do
            local c = tonumber(u[k]) or 0
