task.spawn(function()
    while RUNNING do
        pcall(function()
            local cash = M.cash()
            local now = os.clock()
            S.cash0 = S.cash0 or cash
            local inc = M.income() * (tonumber(lp:GetAttribute("CashMultiplier")) or 1)
            S.hist[#S.hist + 1] = { now, inc }
            while #S.hist > 2 and now - S.hist[1][1] > 300 do table.remove(S.hist, 1) end
            local d = M.data()
            local full, total = 0, 0
            for _, s in ipairs(M.pads()) do total += 1 if s:GetAttribute("State") == "Character" then full += 1 end end
            setText(UI.s1, __T["Doing: "] .. S.task)
            setText(UI.s2, string.format(__T["Cash $%s · Income $%s/s"], M.fmt(cash), M.fmt(inc)))
            local h0 = S.hist[1] and S.hist[1][2] or inc
            setText(UI.s3, string.format(__T["Income %s in %dm"], h0 > 0 and string.format("x%.2f", inc / h0) or "-", math.floor((now - (S.hist[1] and S.hist[1][1] or now)) / 60)))
            setText(UI.s4, string.format(__T["Pads %d/%d · Tier %s"], full, total, tostring(d.ConveyorTier or "?")))
            setText(UI.s5, string.format(__T["Cubes %d · Opened %d · Swapped %d · Sold %d\nObbies %d · Towers %d · Market %d"], S.cubes, S.opened, S.replaced, S.sold, S.obbies, S.towers, S.market))
            setText(UI.u1, string.format(__T["Levels %d · Upgrades %d · Tiers %d\nGrade rolls %d · Trait rolls %d"], S.levels, S.upgrades, S.tiers, S.grades, S.traits))
            local u = d.Utility or {}
            setText(UI.r1, string.format(__T["Claimed %d · Fingers %d\nRanking fingers %s · Trait fingers %s"], S.claims, S.fingers, tostring(u.GradeToken or 0), tostring(u.TraitToken or 0)))
        end)
        task.wait(0.5)
    end
end)
